xm21 N007 vp N004 VDD sky130_fd_pr__pfet_01v8 w={W_xm21} l={L_xm21}
xm22 N008 vm N004 VDD sky130_fd_pr__pfet_01v8 w={W_xm22} l={L_xm22}

* Bias circuit (Fig. 20.15)
.subckt SUB_1 Vbiasn Vbiasp VDD GND
  xmsu2 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xmsu2} l={L_xmsu2}
  xmsu1 N001 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  xmsu3 VDD N001 Vbiasn 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  xm3 Vbiasn Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm31} l={L_xm31}
  xm4 Vbiasp Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm31} l={L_xm31}
  xm1 Vbiasn Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  xm2 Vbiasp Vbiasn N002 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  R1 N002 GND 6.5k
.ends SUB_1

* Simulation control
.control
* 1. Operating point and DC current
op
let idd_bias = -i(vdd)
print idd_bias

* 2. DC transfer characteristics and gain
dc Vp 0.895 0.905 0.00001
let gain = deriv(v(out))
meas dc max_gain max gain
meas dc v_switch when v(out)=0.9 rise=1
let vos = v_switch - 0.9
print max_gain vos

* 3. Transient simulation for propagation delay (50 mV overdrive)
tran 0.05n 150n 100n uic
meas tran t_pLH trig v(vp) val=0.9 rise=1 targ v(Out) val=0.9 rise=1
meas tran t_pHL trig v(vp) val=0.9 fall=1 targ v(Out) val=0.9 fall=1
let t_delay = (t_pLH + t_pHL) / 2
print t_pLH t_pHL t_delay

quit
.endc
.end

